mapper.select:
SELECT m.id, m.name, m.is_deleted AS isDeleted, COUNT(l.id) AS totalLoginCount, MAX(l.access_date) AS lastAccessDate FROM members m LEFT JOIN member_login_history l ON l.member_id = m.id
AND l.access_date >= #{fromDate}
m.id = #{memberId}
AND m.is_deleted = #{isDeleted}
GROUP BY m.id, m.name, m.is_deleted
